import 'dart:ui';

import 'engine.dart';
import 'levels_data.dart';

/// Greedy solver: repeatedly fire any line whose FULL flight (head circle
/// sweeping `arc` units along the ray at 0.4 arc steps, Unity physics parity)
/// is collision-free against all remaining lines. Levels generated by
/// placement construction are guaranteed solvable in reverse placement order;
/// this solver discovers any valid order.
class Solver {
  /// Returns a valid clearing order (line indices), or null if stuck.
  static List<int>? solve(LevelDef def) {
    final eng = PuzzleEngine(def);
    final remaining = List<LineRuntime>.from(eng.lines);
    final order = <int>[];
    while (remaining.isNotEmpty) {
      int? pick;
      for (final l in remaining) {
        if (flightIsClear(l, remaining)) {
          pick = l.index;
          break;
        }
      }
      if (pick == null) return null;
      order.add(pick);
      remaining.removeWhere((l) => l.index == pick);
    }
    return order;
  }

  /// Would firing [line] now be collision-free until cleared?
  static bool flightIsClear(LineRuntime line, List<LineRuntime> remaining) {
    final start = line.headArc; // == L0 at s=0
    final travel = line.arc;
    final steps = travel / kPhysicsStepArc;
    final n = steps.floor();
    for (int k = 1; k <= n; k++) {
      final a = start + kPhysicsStepArc * k;
      final head = line.pointAtExtArc(a);
      for (final other in remaining) {
        if (other.index == line.index || !other.isActive) continue;
        if (_headHits(head, other)) return false;
      }
    }
    // final exact position
    final head = line.pointAtExtArc(start + travel);
    for (final other in remaining) {
      if (other.index == line.index || !other.isActive) continue;
      if (_headHits(head, other)) return false;
    }
    return true;
  }

  static bool _headHits(Offset head, LineRuntime other) {
    // head vs head (works at rest and mid-flight)
    final oh = other.headPos;
    if ((head - oh).distance < 2 * kHeadRadius) return true;
    final segs = other.windowSegments();
    for (final seg in segs) {
      if (LineRuntime.circleHitsBox(head, kHeadRadius, seg[0], seg[1])) {
        return true;
      }
    }
    return false;
  }

  /// First safe line to fire right now given live engine state (for hints).
  static int? hint(PuzzleEngine eng) {
    for (final l in eng.lines) {
      if (l.state != LineState.idle) continue;
      if (flightIsClear(l, eng.lines)) return l.index;
    }
    return null;
  }
}

/// Lookahead bot used by tests: fires each verified-safe line directly and
/// simulates the engine (dt=1/60) until the level is fully cleared.
class Bot {
  static List<int> play(PuzzleEngine eng) {
    final fired = <int>[];
    int guard = 0;
    while (!eng.won && !eng.lost && guard++ < 10000) {
      int? pick;
      for (final l in eng.lines) {
        if (l.state != LineState.idle) continue;
        if (Solver.flightIsClear(l, eng.lines)) {
          pick = l.index;
          break;
        }
      }
      if (pick == null) break; // unsolvable state
      final line = eng.lines[pick];
      line.startFlight();
      eng.started = true;
      fired.add(pick);
      // simulate until this line is done (physics parity inside tick)
      int sub = 0;
      while (eng.lines[pick].state == LineState.flying &&
          sub++ < 100000 &&
          !eng.lost) {
        eng.tick(1 / 60);
      }
    }
    return fired;
  }
}
